/* xgaigu – built-in music library.
 * 300 original instrumental backing tracks, composed procedurally (chords, bass, drums, melody) and
 * rendered on demand with the Web Audio API. Because they are generated by code they carry no third-party
 * copyright, so any user can put them under a video. Real royalty-free MP3 files can also be listed in
 * /data/music.json (see README) and will appear in the same list. */
(() => {
'use strict';

const KEYS = ['C', 'C#', 'D', 'Eb', 'E', 'F', 'F#', 'G', 'Ab', 'A', 'Bb', 'B'];
const MAJOR = [0, 2, 4, 5, 7, 9, 11], MINOR = [0, 2, 3, 5, 7, 8, 10];
const PROG = {
  major: [[0, 4, 5, 3], [0, 3, 4, 0], [0, 5, 3, 4], [5, 3, 0, 4], [0, 2, 5, 3], [1, 4, 0, 0], [0, 4, 1, 3], [3, 4, 2, 5]],
  minor: [[0, 5, 2, 6], [0, 3, 6, 2], [0, 6, 5, 6], [5, 6, 0, 0], [0, 2, 3, 6], [0, 5, 3, 4], [0, 3, 0, 4], [2, 6, 0, 0]],
};

// k/s/h/c/b/a = 16-step patterns (x = hit, o = open hat / accent). chord: how chords are played. bass: bass line style.
const STYLES = [
  { id: 'lofi', name: 'Lofi Chill', bpm: [68, 84], swing: 0.2, k: 'x.....x...x.....', s: '....x.......x...', h: 'x.x.x.x.x.x.x.x.', chord: 'keys', bass: 'sub', lead: 'soft', sev: true, rev: 0.45, vol: 0.9 },
  { id: 'pop', name: 'Pop Vui Tươi', bpm: [102, 122], swing: 0, k: 'x...x...x...x...', s: '....x.......x...', h: '..x...x...x...x.', chord: 'pluck', cp: 'x..x..x.x..x..x.', bass: 'saw', lead: 'bell', rev: 0.25, vol: 1 },
  { id: 'edm', name: 'EDM Sôi Động', bpm: [124, 130], swing: 0, k: 'x...x...x...x...', s: '........x.......', h: '..o...o...o...o.', chord: 'stab', cp: 'x..x..x...x..x..', bass: 'pump', lead: 'saw', pump: true, rev: 0.2, vol: 1 },
  { id: 'ballad', name: 'Ballad Lãng Mạn', bpm: [58, 72], swing: 0, k: 'x.......x.......', s: '', h: '', chord: 'arp', bass: 'sub', lead: 'soft', sev: true, rev: 0.6, vol: 0.9 },
  { id: 'acoustic', name: 'Acoustic Nhẹ Nhàng', bpm: [88, 104], swing: 0.05, k: 'x.......x.x.....', s: '....x.......x...', h: 'x.x.x.x.x.x.x.x.', chord: 'strum', bass: 'sub', lead: 'pluck', rev: 0.3, vol: 0.9, soft: true },
  { id: 'trap', name: 'Hip-hop Trap', bpm: [132, 148], swing: 0, k: 'x.....x...x.....', s: '........x.......', h: 'xxxxxxxxxxxxxxxx', chord: 'keys', bass: '808', lead: 'bell', rev: 0.3, vol: 1 },
  { id: 'disco', name: 'Disco Sàn Nhảy', bpm: [112, 122], swing: 0, k: 'x...x...x...x...', s: '....x.......x...', h: '..o...o...o...o.', chord: 'stab', cp: '..x...x...x...x.', bass: 'disco', lead: 'saw', rev: 0.2, vol: 1 },
  { id: 'piano', name: 'Piano Cảm Xúc', bpm: [64, 80], swing: 0, k: '', s: '', h: '', chord: 'arp2', bass: 'sub', lead: 'soft', sev: true, rev: 0.55, vol: 0.9 },
  { id: 'ambient', name: 'Ambient Thư Giãn', bpm: [56, 68], swing: 0, k: '', s: '', h: '', chord: 'pad', bass: 'sub', lead: 'bell', sev: true, rev: 0.8, vol: 0.85 },
  { id: 'latin', name: 'Latin Sôi Động', bpm: [92, 100], swing: 0, k: 'x...x...x...x...', s: '...x..x....x..x.', h: 'x.x.x.x.x.x.x.x.', chord: 'stab', cp: 'x..x..x.x..x..x.', bass: 'sub', lead: 'pluck', rev: 0.25, vol: 1 },
  { id: 'synth', name: 'Synthwave Retro', bpm: [98, 110], swing: 0, k: 'x...x...x...x...', s: '....x.......x...', h: 'x.x.x.x.x.x.x.x.', chord: 'arp16', bass: 'saw', lead: 'saw', rev: 0.4, vol: 1 },
  { id: 'jazz', name: 'Jazz Cà Phê', bpm: [100, 124], swing: 0.33, k: 'x.......x.......', s: '', h: 'x..xx..xx..xx..x', chord: 'keys', bass: 'walk', lead: 'soft', sev: true, rev: 0.35, vol: 0.9, soft: true },
];
const PER_STYLE = 25;

// ---------- helpers ----------
function rngFrom(seed) { let a = seed >>> 0; return () => { a = (a + 0x6D2B79F5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
function hash(str) { let h = 2166136261; for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; }
const mtof = (m) => 440 * Math.pow(2, (m - 69) / 12);

function buildTracks() {
  const out = [];
  for (let n = 1; n <= PER_STYLE; n++) {
    STYLES.forEach((st, si) => {
      const seed = hash(st.id + ':' + n);
      const r = rngFrom(seed);
      const key = Math.floor(r() * 12);
      const mode = n % 2 === 0 ? 'minor' : 'major';
      const bpm = Math.round(st.bpm[0] + r() * (st.bpm[1] - st.bpm[0]));
      out.push({
        id: st.id + '-' + n, style: st.id, styleName: st.name, title: st.name + ' ' + String(n).padStart(2, '0'),
        meta: KEYS[key] + (mode === 'minor' ? 'm' : '') + ' · ' + bpm + ' BPM', key, mode, bpm, seed, order: n * 100 + si,
      });
    });
  }
  return out;
}

// ---------- synthesis ----------
function note(ctx, out, t, f, dur, o) {
  const a = o.a ?? 0.01, d = o.d ?? 0.1, s = o.s ?? 0.7, rel = o.r ?? 0.1, peak = o.g ?? 0.2;
  const osc = ctx.createOscillator(); osc.type = o.type || 'sine'; osc.frequency.value = f; if (o.detune) osc.detune.value = o.detune;
  const g = ctx.createGain();
  g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(peak, t + a);
  const hold = Math.max(t + a + d, t + dur);
  g.gain.linearRampToValueAtTime(peak * s, t + a + d); g.gain.setValueAtTime(peak * s, hold); g.gain.linearRampToValueAtTime(0, hold + rel);
  let head = osc;
  if (o.lp) { const fl = ctx.createBiquadFilter(); fl.type = 'lowpass'; fl.frequency.value = o.lp; fl.Q.value = o.q || 0.7; osc.connect(fl); head = fl; }
  head.connect(g); g.connect(out);
  if (o.vib) { const l = ctx.createOscillator(), lg = ctx.createGain(); l.frequency.value = 5.5; lg.gain.value = o.vib; l.connect(lg); lg.connect(osc.detune); l.start(t); l.stop(hold + rel + 0.05); }
  osc.start(t); osc.stop(hold + rel + 0.05);
}

function makeNoise(ctx) { const b = ctx.createBuffer(1, ctx.sampleRate, ctx.sampleRate), d = b.getChannelData(0); for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1; return b; }
function noiseHit(ctx, out, t, buf, dur, g0, type, freq) {
  const src = ctx.createBufferSource(); src.buffer = buf; src.loop = true;
  const fl = ctx.createBiquadFilter(); fl.type = type; fl.frequency.value = freq;
  const g = ctx.createGain(); g.gain.setValueAtTime(g0, t); g.gain.exponentialRampToValueAtTime(0.001, t + dur);
  src.connect(fl); fl.connect(g); g.connect(out); src.start(t, Math.random() * 0.5); src.stop(t + dur + 0.02);
}
function kick(ctx, out, t, v) {
  const o = ctx.createOscillator(), g = ctx.createGain(); o.type = 'sine';
  o.frequency.setValueAtTime(150, t); o.frequency.exponentialRampToValueAtTime(42, t + 0.13);
  g.gain.setValueAtTime(0.9 * v, t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.38);
  o.connect(g); g.connect(out); o.start(t); o.stop(t + 0.4);
}
function snare(ctx, out, t, v, nb, soft) {
  noiseHit(ctx, out, t, nb, soft ? 0.13 : 0.2, (soft ? 0.22 : 0.4) * v, 'highpass', 1700);
  note(ctx, out, t, 190, 0.09, { type: 'triangle', g: 0.25 * v, a: 0.001, d: 0.08, s: 0, r: 0.02 });
}
function hat(ctx, out, t, v, nb, open) { noiseHit(ctx, out, t, nb, open ? 0.2 : 0.05, (open ? 0.1 : 0.07) * v, 'highpass', 7500); }

// ---------- composer / renderer ----------
async function renderTrack(track, seconds) {
  const st = STYLES.find((x) => x.id === track.style);
  // Rendered as a seamless loop of whole bars (a multiple of 4 so the chord progression lines up), at most ~28 s;
  // the editor loops it under the video. This keeps generation fast even for long videos.
  const sr = 44100, step = 60 / track.bpm / 4, bar = step * 16;
  const nBars = Math.max(4, Math.ceil(Math.min(seconds, 28) / bar / 4) * 4), total = nBars * bar, len = Math.ceil(total * sr);
  const ctx = new OfflineAudioContext(1, len, sr);
  const r = rngFrom(track.seed ^ 0x9e3779b9);
  const nb = makeNoise(ctx);

  const mg = 0.6 * (st.vol || 1);
  const master = ctx.createGain();
  const comp = ctx.createDynamicsCompressor(); comp.threshold.value = -16; comp.ratio.value = 6;
  master.connect(comp); comp.connect(ctx.destination);
  master.gain.setValueAtTime(mg, 0);

  const rev = ctx.createConvolver(); { const il = Math.floor(sr * 1.8), ib = ctx.createBuffer(1, il, sr), d = ib.getChannelData(0); for (let i = 0; i < il; i++) d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / il, 2.6); rev.buffer = ib; }
  const revSend = ctx.createGain(); revSend.gain.value = st.rev; revSend.connect(rev); rev.connect(master);
  const dry = ctx.createGain(); dry.connect(master); dry.connect(revSend);
  const drums = ctx.createGain(); drums.gain.value = st.soft ? 0.55 : 1; drums.connect(master);
  const melodic = ctx.createGain(); melodic.connect(dry); // chords/bass/lead (pumped for EDM)

  const scale = track.mode === 'minor' ? MINOR : MAJOR;
  const prog = PROG[track.mode][Math.floor(r() * PROG[track.mode].length)];
  const rootMidi = 48 + track.key;
  const degMidi = (idx) => rootMidi + scale[((idx % 7) + 7) % 7] + 12 * Math.floor(idx / 7);
  const chordOf = (deg) => { const c = [degMidi(deg), degMidi(deg + 2), degMidi(deg + 4)]; if (st.sev) c.push(degMidi(deg + 6)); return c; };
  const pent = (track.mode === 'minor' ? [0, 3, 5, 7, 10] : [0, 2, 4, 7, 9]);
  const pentMidi = (i) => rootMidi + 24 + pent[((i % 5) + 5) % 5] + 12 * Math.floor(i / 5);

  // 2-bar melodic motif: 8 positions (every 2 steps) with rests
  const motif = Array.from({ length: 16 }, (_, i) => (i % 2 === 0 && r() > 0.28 ? Math.floor(r() * 7) - 1 : null));
  const swingAt = (s) => (s % 2 === 1 ? st.swing * step : 0);
  const pat = (p, s) => p && p[s % 16] && p[s % 16] !== '.' ? p[s % 16] : null;
  const introBars = st.k ? 2 : 0;

  if (st.pump) for (let t = 0; t < total; t += step * 4) { melodic.gain.setValueAtTime(0.25, t); melodic.gain.linearRampToValueAtTime(1, t + step * 3); }

  for (let b = 0; b < nBars; b++) {
    const t0 = b * bar, chord = chordOf(prog[b % 4]), rootDeg = prog[b % 4];
    const rootNote = chord[0] - 12;
    const inIntro = b < introBars;

    // chords
    if (st.chord === 'keys' || st.chord === 'pad') {
      chord.forEach((m, i) => { const o = { type: st.chord === 'pad' ? 'sawtooth' : 'triangle', g: st.chord === 'pad' ? 0.045 : 0.075, a: st.chord === 'pad' ? 0.8 : 0.03, d: 0.4, s: 0.7, r: 0.6, lp: st.chord === 'pad' ? 1200 : 2200, vib: 6 }; note(ctx, melodic, t0, mtof(m), bar * 0.96, o); note(ctx, melodic, t0, mtof(m), bar * 0.96, { ...o, type: 'sine', g: o.g * 0.8, detune: i % 2 ? 6 : -6 }); });
    } else if (st.chord === 'pluck' || st.chord === 'stab') {
      for (let s = 0; s < 16; s++) if (pat(st.cp, s)) chord.forEach((m) => note(ctx, melodic, t0 + s * step + swingAt(s), mtof(m + 12), step * 1.6, { type: st.chord === 'stab' ? 'sawtooth' : 'triangle', g: 0.05, a: 0.004, d: 0.1, s: 0.2, r: 0.08, lp: st.chord === 'stab' ? 3000 : 2400 }));
    } else if (st.chord === 'strum') {
      chord.forEach((m, i) => note(ctx, melodic, t0 + i * 0.018, mtof(m), bar * 0.9, { type: 'triangle', g: 0.07, a: 0.004, d: 0.5, s: 0.25, r: 0.3, lp: 2600 }));
      for (let s = 4; s < 16; s += 4) chord.forEach((m, i) => note(ctx, melodic, t0 + s * step + i * 0.012, mtof(m + 12), step * 3, { type: 'triangle', g: 0.04, a: 0.004, d: 0.3, s: 0.2, r: 0.2, lp: 2400 }));
    } else if (st.chord === 'arp' || st.chord === 'arp2' || st.chord === 'arp16') {
      const every = st.chord === 'arp16' ? 1 : st.chord === 'arp2' ? 4 : 2;
      for (let s = 0, i = 0; s < 16; s += every, i++) {
        const m = chord[i % chord.length] + (st.chord === 'arp16' ? 12 : 0) + ((i % 8) >= 4 && st.chord !== 'arp16' ? 12 : 0);
        const o = st.chord === 'arp16' ? { type: 'sawtooth', g: 0.05, a: 0.003, d: 0.08, s: 0.3, r: 0.05, lp: 2200 } : { type: 'triangle', g: 0.11, a: 0.004, d: 0.35, s: 0.2, r: 0.5, lp: 3200 };
        note(ctx, melodic, t0 + s * step, mtof(m), step * every * 1.3, o);
        if (st.chord !== 'arp16') note(ctx, melodic, t0 + s * step, mtof(m), step * every * 1.3, { ...o, type: 'sine', g: o.g * 0.7 });
      }
      if (st.chord !== 'arp16') chord.slice(0, 3).forEach((m) => note(ctx, melodic, t0, mtof(m), bar, { type: 'sine', g: 0.035, a: 0.5, d: 0.4, s: 0.7, r: 0.6 }));
    }

    // bass
    const bm = rootNote - (rootNote > 46 ? 12 : 0);
    if (st.bass === 'sub') note(ctx, melodic, t0, mtof(bm), bar * 0.95, { type: 'sine', g: 0.3, a: 0.02, d: 0.2, s: 0.8, r: 0.15 });
    else if (st.bass === '808') { for (const s of [0, 6, 10]) note(ctx, melodic, t0 + s * step, mtof(bm), step * (s === 10 ? 6 : 4), { type: 'sine', g: 0.4, a: 0.005, d: 0.4, s: 0.6, r: 0.2 }); }
    else if (st.bass === 'saw' || st.bass === 'pump') { for (let s = 0; s < 16; s += 2) note(ctx, melodic, t0 + s * step, mtof(bm), step * 1.8, { type: 'sawtooth', g: 0.13, a: 0.005, d: 0.1, s: 0.6, r: 0.05, lp: 700 }); }
    else if (st.bass === 'disco') { for (let s = 0; s < 16; s += 2) note(ctx, melodic, t0 + s * step, mtof(bm + (s % 4 === 2 ? 12 : 0)), step * 1.6, { type: 'sawtooth', g: 0.14, a: 0.004, d: 0.1, s: 0.5, r: 0.04, lp: 900 }); }
    else if (st.bass === 'walk') { const tones = [chord[0], chord[1], chord[2], chord[1]]; for (let q = 0; q < 4; q++) note(ctx, melodic, t0 + q * 4 * step + swingAt(0), mtof(tones[q] - 12), step * 3.6, { type: 'triangle', g: 0.28, a: 0.01, d: 0.15, s: 0.6, r: 0.1, lp: 900 }); }

    // drums
    if (!inIntro || b >= 1) for (let s = 0; s < 16; s++) {
      const t = t0 + s * step + swingAt(s);
      if (b >= introBars - 1 && pat(st.k, s)) kick(ctx, drums, t, 1);
      if (!inIntro && pat(st.s, s)) snare(ctx, drums, t, 1, nb, st.soft);
      const hp = pat(st.h, s);
      if (hp && (b >= 1 || !st.k)) hat(ctx, drums, t, 0.6 + 0.4 * r(), nb, hp === 'o');
    }

    // lead (after the intro)
    if (b >= (st.k ? 2 : 1) && st.lead) {
      for (let i = 0; i < 8; i++) {
        let deg = motif[(b % 2) * 8 + i]; // 2-bar motif: 8 positions per bar, null = rest
        if (deg === null || deg === undefined) continue;
        if (b % 4 === 3 && i > 5) deg += 2; // small variation at phrase end
        const m = pentMidi(deg + (prog[b % 4] % 5));
        const t = t0 + i * 2 * step + swingAt(i * 2);
        const L = {
          soft: { type: 'sine', g: 0.11, a: 0.02, d: 0.2, s: 0.5, r: 0.3, vib: 8 },
          bell: { type: 'sine', g: 0.1, a: 0.003, d: 0.6, s: 0.1, r: 0.8 },
          pluck: { type: 'triangle', g: 0.1, a: 0.003, d: 0.25, s: 0.15, r: 0.15, lp: 3000 },
          saw: { type: 'sawtooth', g: 0.06, a: 0.01, d: 0.12, s: 0.5, r: 0.12, lp: 2600 },
        }[st.lead];
        note(ctx, melodic, t, mtof(m), step * 3, L);
        if (st.lead === 'bell') note(ctx, melodic, t, mtof(m) * 2, step * 3, { ...L, g: 0.03 });
      }
    }
  }

  const buf = await ctx.startRendering();
  buf.loopSeconds = total;
  return buf;
}

function toWav(buf) {
  const n = buf.length, sr = buf.sampleRate, ch = buf.getChannelData(0);
  const ab = new ArrayBuffer(44 + n * 2), v = new DataView(ab);
  const w = (o, s) => { for (let i = 0; i < s.length; i++) v.setUint8(o + i, s.charCodeAt(i)); };
  w(0, 'RIFF'); v.setUint32(4, 36 + n * 2, true); w(8, 'WAVE'); w(12, 'fmt '); v.setUint32(16, 16, true); v.setUint16(20, 1, true);
  v.setUint16(22, 1, true); v.setUint32(24, sr, true); v.setUint32(28, sr * 2, true); v.setUint16(32, 2, true); v.setUint16(34, 16, true); w(36, 'data'); v.setUint32(40, n * 2, true);
  for (let i = 0; i < n; i++) { const s = Math.max(-1, Math.min(1, ch[i])); v.setInt16(44 + i * 2, s < 0 ? s * 0x8000 : s * 0x7fff, true); }
  return new Blob([ab], { type: 'audio/wav' });
}

const tracks = buildTracks();
// Optional extra tracks: real royalty-free files listed in /data/music.json  [{ "id", "title", "style", "meta", "url" }]
async function loadCatalog() {
  try {
    const list = await (await fetch('/data/music.json', { cache: 'no-cache' })).json();
    if (Array.isArray(list)) for (const t of list) if (t && /^\/|^https:\/\//.test(t.url || '') && t.title) tracks.unshift({ id: 'file-' + (t.id || t.title), style: t.style || 'file', styleName: t.style || 'Nhạc có sẵn', title: t.title, meta: t.meta || '', url: t.url });
  } catch {}
}

async function renderFile(track, seconds) {
  if (track.url) { const blob = await (await fetch(track.url)).blob(); return new File([blob], track.title, { type: blob.type || 'audio/mpeg' }); }
  const buf = await renderTrack(track, Math.max(10, Math.min(100, seconds)));
  return new File([toWav(buf)], track.title + '.wav', { type: 'audio/wav' });
}

const ready = loadCatalog();
window.XGMusic = { ready, tracks, styles: STYLES.map((s) => ({ id: s.id, name: s.name })), renderFile, loadCatalog, renderTrack, toWav };
})();
